<?php

namespace Database\Factories\Person;

use App\Domain\Person\Enums\Gender;
use App\Models\Person\Person;
use App\Models\User;
use Faker\Factory as FakerFactory;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * People with names from mixed Faker locales (en_US, ko_KR, zh_CN). Emails use the
 * reserved .test domain; no real-looking national ids are generated by default.
 *
 * @extends Factory<Person>
 */
class PersonFactory extends Factory
{
    protected $model = Person::class;

    /**
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        $locale = fake()->randomElement(['en_US', 'ko_KR', 'zh_CN']);
        $local = FakerFactory::create($locale);
        $gender = fake()->randomElement([Gender::Female, Gender::Male]);
        $romanFamily = FakerFactory::create('en_US')->lastName();
        $romanGiven = FakerFactory::create('en_US')->firstName($gender === Gender::Female ? 'female' : 'male');

        $variants = match ($locale) {
            'ko_KR' => ['ko' => $local->lastName().$local->firstName()],
            'zh_CN' => ['zh_CN' => $local->lastName().$local->firstName()],
            default => null,
        };

        return [
            'family_name' => $romanFamily,
            'given_name' => $romanGiven,
            'name_variants' => $variants,
            'birth_date' => fake()->dateTimeBetween('-30 years', '-18 years')->format('Y-m-d'),
            'gender' => $gender,
            'email' => fake()->unique()->userName().'@example.test',
            'phone' => fake()->numerify('010-####-####'),
        ];
    }

    /**
     * A fictional national id (letters cannot occur in real numbers).
     */
    public function withNationalId(?string $value = null): static
    {
        return $this->state(fn () => ['national_id_encrypted' => $value ?? 'TEST-'.fake()->unique()->numerify('##########')]);
    }

    public function withAccount(): static
    {
        return $this->afterCreating(function (Person $person) {
            User::factory()->create(['person_id' => $person->id, 'email' => $person->email ?? fake()->unique()->safeEmail(), 'name' => null]);
        });
    }
}
